package com.example.javaanalyzer.ir;

import java.util.List;

/**
 * A MyBatis mapper (FR-15). Method signatures are in the {@link TypeModel} of the interface; a
 * method without a matching statement has no SQL known from the sources. Methods generated by a
 * base interface such as MyBatis-Plus {@code BaseMapper} are not inferred.
 *
 * @param interfaceType qualified name of the mapper interface; null when an XML namespace matches
 *     no interface in the project
 * @param namespace namespace of the XML files; null when the mapper has no XML
 * @param xmlFiles XML files of the mapper, relative to the project root with forward slashes
 * @param baseType the MyBatis-Plus base interface as written; null when it does not extend one
 */
public record MapperModel(
    String interfaceType,
    String namespace,
    List<String> xmlFiles,
    TypeRef baseType,
    List<MapperStatementModel> statements) {

  public MapperModel {
    xmlFiles = List.copyOf(xmlFiles);
    statements = List.copyOf(statements);
  }
}
